===================================================================
--- a/src/scene.js
+++ b/src/scene.js
@@ -1,25 +1,75 @@
 // Preserve every semantic object, material, geometry, animation and picking identity.
 // semanticId identifies an ordinary mesh; semanticIds identifies each instance.
 export function createWorld(THREE, scene) {
+  // Parameters
   const count = 1600;
-  const robots = [];
+  const columns = 40;
+  const rows = Math.ceil(count / columns);
+  
+  // Geometry
+  const geometry = new THREE.BoxGeometry(.72, .48, .94);
+
+  // Color/material split
+  const material0 = new THREE.MeshStandardMaterial({color: 0xf59b52, roughness: .42, metalness: .35});
+  const material1 = new THREE.MeshStandardMaterial({color: 0x4f8ca8, roughness: .42, metalness: .35});
+
+  // Compute which instance gets which material
+  const group0Idxs = [];
+  const group1Idxs = [];
   for (let i = 0; i < count; i++) {
-    const geometry = new THREE.BoxGeometry(.72, .48, .94);
-    const material = new THREE.MeshStandardMaterial({color: i % 3 === 0 ? 0xf59b52 : 0x4f8ca8, roughness: .42, metalness: .35});
-    const mesh = new THREE.Mesh(geometry, material);
-    mesh.userData.semanticId = 'robot-' + i;
-    scene.add(mesh);
-    robots.push(mesh);
+    if (i % 3 === 0) group0Idxs.push(i); else group1Idxs.push(i);
   }
+  // Create InstancedMeshes
+  const mesh0 = new THREE.InstancedMesh(geometry, material0, group0Idxs.length);
+  const mesh1 = new THREE.InstancedMesh(geometry, material1, group1Idxs.length);
+
+  // Assign identity: for picking, each robot's semanticId mapped per instance
+  mesh0.userData.semanticIds = group0Idxs.map(i => 'robot-' + i);
+  mesh1.userData.semanticIds = group1Idxs.map(i => 'robot-' + i);
+  // For completeness, store which instance corresponds to which slot
+  mesh0.userData.instanceToRobotIndex = group0Idxs;
+  mesh1.userData.instanceToRobotIndex = group1Idxs;
+
+  // Add to scene
+  scene.add(mesh0);
+  scene.add(mesh1);
+
+  // Prepare working state to avoid per-frame allocations
+  const dummy = new THREE.Object3D();
+  // Store the math required for update, indexing into correct instanced mesh
   return {
     update(t) {
-      for (let i = 0; i < count; i++) {
-        const column = i % 40;
-        const row = Math.floor(i / 40);
-        const position = new THREE.Vector3((column - 19.5) * 1.25, .32 + Math.sin(t * 1.8 + i * .13) * .04, (row - Math.floor(count / 40) / 2) * 1.3 + Math.sin(t * .4 + column * .2) * .4);
-        robots[i].position.copy(position);
-        robots[i].rotation.y = Math.sin(t * .5 + i * .04) * .18;
+      // Group 0: (i % 3 == 0)
+      for (let inst = 0; inst < group0Idxs.length; inst++) {
+        const i = group0Idxs[inst];
+        const column = i % columns;
+        const row = Math.floor(i / columns);
+        dummy.position.set(
+          (column - (columns - 0.5)) * 1.25,
+          .32 + Math.sin(t * 1.8 + i * .13) * .04,
+          (row - (rows / 2)) * 1.3 + Math.sin(t * .4 + column * .2) * .4
+        );
+        dummy.rotation.set(0, Math.sin(t * .5 + i * .04) * .18, 0);
+        dummy.updateMatrix();
+        mesh0.setMatrixAt(inst, dummy.matrix);
       }
+      mesh0.instanceMatrix.needsUpdate = true;
+      
+      // Group 1: (i % 3 != 0)
+      for (let inst = 0; inst < group1Idxs.length; inst++) {
+        const i = group1Idxs[inst];
+        const column = i % columns;
+        const row = Math.floor(i / columns);
+        dummy.position.set(
+          (column - (columns - 0.5)) * 1.25,
+          .32 + Math.sin(t * 1.8 + i * .13) * .04,
+          (row - (rows / 2)) * 1.3 + Math.sin(t * .4 + column * .2) * .4
+        );
+        dummy.rotation.set(0, Math.sin(t * .5 + i * .04) * .18, 0);
+        dummy.updateMatrix();
+        mesh1.setMatrixAt(inst, dummy.matrix);
+      }
+      mesh1.instanceMatrix.needsUpdate = true;
     }
   };
 }
